/* eslint-disable -- SPK-07 spike tooling: untyped .mjs harness, dynamic imports of arm modules, Node globals. */
// SPK-07 statistics and run-data readers. Screening evidence only (not ADR-SC-005 D-C evidence).
// Everything here is pure and seeded so a report can be regenerated byte-for-byte from a run dir.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';

export const Z95 = 1.959963984540054;

/** Wilson score interval for k successes out of n (default 95%). */
export function wilson(k, n, z = Z95) {
  if (!(n > 0)) return { k, n, p: null, lo: null, hi: null };
  const p = k / n;
  const z2 = z * z;
  const denominator = 1 + z2 / n;
  const centre = (p + z2 / (2 * n)) / denominator;
  const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denominator;
  return { k, n, p, lo: Math.max(0, centre - half), hi: Math.min(1, centre + half) };
}

const logFactorial = (() => {
  const cache = [0];
  return (n) => { for (let i = cache.length; i <= n; i++) cache[i] = cache[i - 1] + Math.log(i); return cache[n]; };
})();

/** P(X <= k) for X ~ Binomial(n, 0.5), summed in log space (exact, no underflow for large n). */
export function binomialCdfHalf(k, n) {
  if (k < 0) return 0;
  if (k >= n) return 1;
  let total = 0;
  for (let i = 0; i <= k; i++) total += Math.exp(logFactorial(n) - logFactorial(i) - logFactorial(n - i) - n * Math.LN2);
  return Math.min(1, total);
}

/**
 * Exact McNemar test: two-sided binomial test on the discordant pairs.
 * b = pairs where only arm X succeeded, c = pairs where only arm Y succeeded.
 */
export function mcnemarExact(b, c) {
  const n = b + c;
  if (n === 0) return { b, c, n, p: 1 };
  return { b, c, n, p: Math.min(1, 2 * binomialCdfHalf(Math.min(b, c), n)) };
}

/** Deterministic seeding: string -> uint32 -> mulberry32. */
export function seedFrom(text) { return createHash('sha256').update(String(text)).digest().readUInt32LE(0); }
export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function shuffled(items, rng) {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [out[i], out[j]] = [out[j], out[i]]; }
  return out;
}

/** Strict majority of a boolean list (ties are not a majority). Empty -> null. */
export function majority(flags) {
  if (flags.length === 0) return null;
  return flags.filter(Boolean).length * 2 > flags.length;
}

/** Nearest-rank percentile (q in 0..100) of a numeric list; null when empty. */
export function percentile(values, q) {
  const sorted = values.filter(v => typeof v === 'number' && Number.isFinite(v)).sort((a, b) => a - b);
  if (sorted.length === 0) return null;
  return sorted[Math.min(sorted.length - 1, Math.max(0, Math.ceil((q / 100) * sorted.length) - 1))];
}
export const mean = values => (values.length === 0 ? null : values.reduce((s, v) => s + v, 0) / values.length);

/** Implied k-step completion rate from a per-step rate. */
export const impliedCompletion = (p, k) => (p === null ? null : p ** k);

/**
 * Cluster bootstrap of rate(x) - rate(y). `clusters` is a list of { id, x: {k, n}, y: {k, n} } (one per task);
 * a resample draws tasks with replacement, pooled rate per arm = sum(k) / sum(n). Percentile 95% CI.
 */
export function clusterBootstrapDiff(clusters, { resamples = 10000, seed = 1, alpha = 0.05 } = {}) {
  const usable = clusters.filter(c => c.x.n > 0 && c.y.n > 0);
  const rate = (rows, side) => { let k = 0; let n = 0; for (const r of rows) { k += r[side].k; n += r[side].n; } return n === 0 ? null : k / n; };
  if (usable.length === 0) return { diff: null, lo: null, hi: null, clusters: 0, resamples: 0, seed };
  const diff = rate(usable, 'x') - rate(usable, 'y');
  const rng = mulberry32(typeof seed === 'number' ? seed : seedFrom(seed));
  const diffs = new Float64Array(resamples);
  for (let r = 0; r < resamples; r++) {
    let kx = 0; let nx = 0; let ky = 0; let ny = 0;
    for (let i = 0; i < usable.length; i++) {
      const c = usable[Math.floor(rng() * usable.length)];
      kx += c.x.k; nx += c.x.n; ky += c.y.k; ny += c.y.n;
    }
    diffs[r] = kx / nx - ky / ny;
  }
  const sorted = Array.from(diffs).sort((a, b) => a - b);
  const at = q => sorted[Math.min(sorted.length - 1, Math.max(0, Math.floor(q * sorted.length)))];
  return { diff, lo: at(alpha / 2), hi: at(1 - alpha / 2), clusters: usable.length, resamples, seed };
}

/**
 * Cluster bootstrap of the summed ratio sum(x) / sum(y) (e.g. prompt tokens S1 / A1). Clusters are tasks:
 * [{ id, x: sum, y: sum }]. Percentile 95% CI.
 */
export function clusterBootstrapRatio(clusters, { resamples = 10000, seed = 1, alpha = 0.05 } = {}) {
  const usable = clusters.filter(c => c.x > 0 || c.y > 0);
  const total = (rows, side) => rows.reduce((s, r) => s + r[side], 0);
  if (usable.length === 0 || total(usable, 'y') === 0) return { ratio: null, lo: null, hi: null, clusters: usable.length, resamples: 0, seed };
  const rng = mulberry32(typeof seed === 'number' ? seed : seedFrom(seed));
  const ratios = [];
  for (let r = 0; r < resamples; r++) {
    let x = 0; let y = 0;
    for (let i = 0; i < usable.length; i++) { const c = usable[Math.floor(rng() * usable.length)]; x += c.x; y += c.y; }
    if (y > 0) ratios.push(x / y);
  }
  ratios.sort((a, b) => a - b);
  const at = q => ratios[Math.min(ratios.length - 1, Math.max(0, Math.floor(q * ratios.length)))];
  return { ratio: total(usable, 'x') / total(usable, 'y'), lo: at(alpha / 2), hi: at(1 - alpha / 2), clusters: usable.length, resamples, seed };
}

/**
 * Paired per-unit comparison of arm X against arm Y.
 * `units` is a list of { task, x: boolean[] (per rep), y: boolean[] }.
 * Primary: one outcome per unit = majority over reps. Sensitivity: every rep, paired by rep index.
 */
export function pairedComparison(units, { resamples = 10000, seed = 1, rule = 'majority' } = {}) {
  // rule 'all' (4-hour profile): an arm succeeds on a unit only if EVERY one of its reps succeeds (a 1-rep arm: its single rep).
  const success = flags => (rule === 'all' ? flags.length > 0 && flags.every(Boolean) : majority(flags));
  const usable = units.filter(u => u.x.length > 0 && u.y.length > 0);
  let b = 0; let c = 0; let both = 0; let neither = 0;
  for (const u of usable) {
    const x = success(u.x); const y = success(u.y);
    if (x && !y) b++; else if (!x && y) c++; else if (x) both++; else neither++;
  }
  let sb = 0; let sc = 0;
  for (const u of usable) {
    const len = Math.min(u.x.length, u.y.length);
    for (let i = 0; i < len; i++) { if (u.x[i] && !u.y[i]) sb++; else if (!u.x[i] && u.y[i]) sc++; }
  }
  const byTask = new Map();
  for (const u of usable) {
    const entry = byTask.get(u.task) ?? { id: u.task, x: { k: 0, n: 0 }, y: { k: 0, n: 0 } };
    for (const f of u.x) { entry.x.k += f ? 1 : 0; entry.x.n += 1; }
    for (const f of u.y) { entry.y.k += f ? 1 : 0; entry.y.n += 1; }
    byTask.set(u.task, entry);
  }
  const clusters = [...byTask.values()];
  return {
    units: usable.length, tasks: clusters.length, onlyX: b, onlyY: c, both, neither,
    mcnemar: mcnemarExact(b, c),
    sensitivityAllReps: mcnemarExact(sb, sc),
    bootstrap: clusterBootstrapDiff(clusters, { resamples, seed }),
    rateX: wilson(usable.filter(u => success(u.x)).length, usable.length),
    rateY: wilson(usable.filter(u => success(u.y)).length, usable.length),
  };
}

// ---- run-data helpers -------------------------------------------------------------------------------------------

export function readJsonl(path) {
  if (!existsSync(path)) return [];
  const rows = [];
  for (const line of readFileSync(path, 'utf8').split('\n')) {
    if (line.trim() === '') continue;
    try { rows.push(JSON.parse(line)); } catch { /* a torn final line from a killed run is ignored */ }
  }
  return rows;
}
export function readJson(path, fallback = null) {
  try { return JSON.parse(readFileSync(path, 'utf8')); } catch { return fallback; }
}
/** Last row wins per key (reruns append). */
export function lastByKey(rows, keyOf = r => r.key) {
  const map = new Map();
  for (const row of rows) map.set(keyOf(row), row);
  return [...map.values()];
}
